      WHEN 'Pro 3' THEN '25'
      WHEN 'Amateur 1' THEN '26'
      WHEN 'Amateur 2' THEN '27'
      WHEN 'Amateur 3' THEN '28'
      WHEN 'Semi Pro 1' THEN '113'
      WHEN 'Semi Pro 2' THEN '114'
      WHEN 'Semi Pro 3' THEN '115'
      WHEN 'Beginner' THEN '81'
      WHEN 'Welcome' THEN '62'
      ELSE NULL END AS division_id,
    h.canonical_player_id::text AS canonical_player_id, h.source_player_id::text AS source_player_id,
    h.historical_player_name, h.course_name, h.difficulty, h.score
  FROM public.historical_monthly_score_observations h
  WHERE h.period_id IN (SELECT DISTINCT period_id FROM source_prepared)
    AND h.score IS NOT NULL
), production_prepared AS (
  SELECT p.*,
    concat_ws('|', p.period_id::text, p.division_id,
      coalesce(p.canonical_player_id, 'source:' || p.source_player_id, 'name:' || p.historical_player_name),
      p.course_name, p.difficulty) AS logical_key
  FROM production_raw p
), production_grouped AS (
  SELECT p.logical_key, min(p.production_observation_id) AS production_observation_id,
    min(p.score) AS production_score_min, max(p.score) AS production_score_max,
    count(*)::integer AS production_physical_row_count
  FROM production_prepared p GROUP BY p.logical_key
), classified AS (
  SELECT s.payload_row, s.source_row, s.source_logical_key, s.logical_key,
    CASE WHEN p.logical_key IS NULL THEN 'MISSING_FROM_PRODUCTION'
         WHEN p.production_score_min = p.production_score_max
          AND p.production_score_min = s.repaired_score THEN 'EXACT_DUPLICATE'
         ELSE 'TRUE_CONFLICT' END AS classification,
    s.score_band, s.period_id, s.period_year, s.period_month, s.period_label,
    s.division, s.division_id, s.canonical_player_id, s.historical_player_name,
    s.source_player_id, s.course_name, s.difficulty, s.score_text, s.repaired_score,
    p.production_observation_id,
    CASE WHEN p.production_score_min = p.production_score_max THEN p.production_score_min ELSE NULL END AS production_score,
    p.production_score_min, p.production_score_max, p.production_physical_row_count
  FROM source_prepared s LEFT JOIN production_grouped p ON p.logical_key = s.logical_key
), production_only AS (
  SELECT p.logical_key, p.production_observation_id, p.production_score_min,
    p.production_score_max, p.production_physical_row_count
  FROM production_grouped p LEFT JOIN source_prepared s ON s.logical_key = p.logical_key
  WHERE s.logical_key IS NULL
), summary AS (
  SELECT jsonb_build_object(
    'batch_number', 12,
    'batch_periods', (SELECT jsonb_agg(DISTINCT period_id) FROM source_prepared),
    'source_payload_rows', (SELECT count(*) FROM source_prepared),
    'scored_identities_in_batch', (SELECT count(DISTINCT historical_player_name) FROM source_prepared),
    'exact_duplicates', (SELECT count(*) FROM classified WHERE classification = 'EXACT_DUPLICATE'),
    'missing_from_production', (SELECT count(*) FROM classified WHERE classification = 'MISSING_FROM_PRODUCTION'),
    'production_only', (SELECT count(*) FROM production_only),
    'true_conflicts', (SELECT count(*) FROM classified WHERE classification = 'TRUE_CONFLICT'),
    'source_zero_rows', (SELECT count(*) FROM source_prepared WHERE score_band = 'ZERO'),
    'zero_exact_duplicates', (SELECT count(*) FROM classified WHERE score_band = 'ZERO' AND classification = 'EXACT_DUPLICATE'),
    'zero_missing_from_production', (SELECT count(*) FROM classified WHERE score_band = 'ZERO' AND classification = 'MISSING_FROM_PRODUCTION'),
    'zero_true_conflicts', (SELECT count(*) FROM classified WHERE score_band = 'ZERO' AND classification = 'TRUE_CONFLICT'),
    'source_negative_rows', (SELECT count(*) FROM source_prepared WHERE score_band = 'NEGATIVE'),
    'negative_exact_duplicates', (SELECT count(*) FROM classified WHERE score_band = 'NEGATIVE' AND classification = 'EXACT_DUPLICATE'),
    'negative_missing_from_production', (SELECT count(*) FROM classified WHERE score_band = 'NEGATIVE' AND classification = 'MISSING_FROM_PRODUCTION'),
    'negative_true_conflicts', (SELECT count(*) FROM classified WHERE score_band = 'NEGATIVE' AND classification = 'TRUE_CONFLICT'),
    'source_positive_rows', (SELECT count(*) FROM source_prepared WHERE score_band = 'POSITIVE'),
    'positive_exact_duplicates', (SELECT count(*) FROM classified WHERE score_band = 'POSITIVE' AND classification = 'EXACT_DUPLICATE'),
    'positive_missing_from_production', (SELECT count(*) FROM classified WHERE score_band = 'POSITIVE' AND classification = 'MISSING_FROM_PRODUCTION'),
    'positive_true_conflicts', (SELECT count(*) FROM classified WHERE score_band = 'POSITIVE' AND classification = 'TRUE_CONFLICT'),
    'production_physical_rows_in_scope', (SELECT count(*) FROM production_raw),
    'production_logical_rows_in_scope', (SELECT count(*) FROM production_grouped),
    'atlantis_quarantine_source_key_absent', NOT EXISTS (SELECT 1 FROM source_prepared WHERE source_logical_key = '221|22|id:8108|Atlantis|easy'),
    'atlantis_nonquarantined_context_rows', (SELECT count(*) FROM source_prepared WHERE period_id = 221 AND division_id = '22' AND historical_player_name = 'PETERK9FLORIDA' AND course_name = 'Atlantis' AND difficulty != 'easy'),
    'amateur_1_3_rows', (SELECT count(*) FROM source_prepared WHERE division_id IN ('26', '27', '28')),
    'september_2026_absent', NOT EXISTS (SELECT 1 FROM source_prepared WHERE period_year = 2026 AND period_month = 9),
    'august_2026_rows', (SELECT count(*) FROM source_prepared WHERE period_year = 2026 AND period_month = 8),
    'august_2026_present', EXISTS (SELECT 1 FROM source_prepared WHERE period_year = 2026 AND period_month = 8)
  ) AS payload
), detail_rows AS (
  SELECT 'ROW_CLASSIFICATION'::text AS result_kind, to_jsonb(c) AS payload FROM classified c
  UNION ALL
  SELECT 'CONFLICT_DETAIL'::text AS result_kind, to_jsonb(c) AS payload FROM classified c WHERE c.classification = 'TRUE_CONFLICT'
  UNION ALL
  SELECT 'PRODUCTION_ONLY'::text AS result_kind, to_jsonb(p) AS payload FROM production_only p
)
SELECT 'SUMMARY'::text AS result_kind, payload FROM summary
UNION ALL SELECT result_kind, payload FROM detail_rows
ORDER BY result_kind, payload;
